import re

def _parse_version(version_string):
    """
    Parses a version string into (major, minor, patch, pre_release_identifiers).
    Build metadata is ignored.
    """
    # Split off build metadata if present (everything after +)
    core_version = version_string.split('+', 1)[0]

    # Split off pre-release if present (everything after -)
    parts = core_version.split('-', 1)
    version_core = parts[0]
    pre_release_str = parts[1] if len(parts) > 1 else None

    # Parse M.M.P
    try:
        major, minor, patch = map(int, version_core.split('.'))
    except ValueError:
        # Should not happen based on assumption, but good practice
        raise ValueError("Invalid major.minor.patch format")

    # Parse pre-release identifiers
    pre_release_identifiers = []
    if pre_release_str:
        pre_release_identifiers = pre_release_str.split('.')

    return major, minor, patch, pre_release_identifiers

def _is_numeric_identifier(identifier):
    """Checks if an identifier consists only of digits."""
    return identifier.isdigit()

def _compare_pre_releases(pr_a, pr_b):
    """
    Compares two lists of pre-release identifiers (e.g., ['alpha', '1']).
    Returns -1 if A < B, 0 if A == B, 1 if A > B.
    """
    len_a = len(pr_a)
    len_b = len(pr_b)

    # Iterate up to the length of the shorter list
    for i in range(min(len_a, len_b)):
        id_a = pr_a[i]
        id_b = pr_b[i]

        is_a_num = _is_numeric_identifier(id_a)
        is_b_num = _is_numeric_identifier(id_b)

        if is_a_num and is_b_num:
            # Both are numeric: compare as integers
            num_a = int(id_a)
            num_b = int(id_b)
            if num_a != num_b:
                return -1 if num_a < num_b else 1
        elif not is_a_num and not is_b_num:
            # Both are text: compare as ASCII strings
            if id_a != id_b:
                return -1 if id_a < id_b else 1
        else:
            # Mixed types: numeric is lower than text
            if is_a_num and not is_b_num:
                return -1  # A (numeric) < B (text)
            else: # not is_a_num and is_b_num
                return 1   # A (text) > B (numeric)

    # If all shared identifiers were equal, compare lengths
    if len_a < len_b:
        return -1  # Shorter is lower
    elif len_a > len_b:
        return 1   # Longer is higher
    else:
        return 0   # Equal

def compare_versions(a, b):
    """
    Compares two version strings (a and b) by Semantic Versioning precedence.
    Returns -1 if a < b, 0 if a == b, 1 if a > b.
    """

    # 1. Parse both versions
    try:
        maj_a, min_a, pat_a, pr_a = _parse_version(a)
        maj_b, min_b, pat_b, pr_b = _parse_version(b)
    except ValueError:
        # Should not happen based on problem constraints, but handles parsing failure
        raise

    # 2. Compare Major, Minor, Patch
    if maj_a != maj_b:
        return -1 if maj_a < maj_b else 1
    if min_a != min_b:
        return -1 if min_a < min_b else 1
    if pat_a != pat_b:
        return -1 if pat_a < pat_b else 1

    # 3. M.M.P are equal. Compare pre-release status.

    # If both have no pre-release, they are equal (0)
    if not pr_a and not pr_b:
        return 0

    # If A has no pre-release (e.g., 1.0.0) and B does (e.g., 1.0.0-alpha), A is higher (1)
    if not pr_a and pr_b:
        return 1

    # If B has no pre-release and A does, B is higher (1)
    if pr_a and not pr_b:
        return -1

    # 4. Both have pre-releases. Use specialized comparison.
    return _compare_pre_releases(pr_a, pr_b)
